q('personalization-form').onsubmit=savePersonalization;q('typesetter-form').onsubmit=e=>saveTypesetter(e);q('typesetter-adapter').onchange=adapterHint;q('test-typesetter').onclick=testTypesetter;q('reset-prompts').onclick=resetPrompts;q('weather-form').onsubmit=e=>saveWeather(e);q('weather-search').onclick=searchWeather;q('weather-query').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();searchWeather()}};q('refresh-weather').onclick=refreshWeather;q('refresh-mcp').onclick=loadMcp;q('toggle-mcp-secret').onclick=()=>{const field=q('mcp-bearer'),visible=field.type==='text';field.type=visible?'password':'text';q('toggle-mcp-secret').textContent=visible?'显示':'隐藏'};document.querySelectorAll('.copy-button').forEach(button=>button.onclick=()=>copyText(q(button.dataset.copyTarget).value));q('refresh-logs').onclick=loadLogs;q('rotate-form').onsubmit=rotate;const logout=async()=>{try{await json('/admin/v1/logout',{method:'POST'})}finally{location.reload()}};q('logout').onclick=logout;q('managed-logout').onclick=logout;q('bootstrap-form').onsubmit=e=>establish('bootstrap',e);q('login-form').onsubmit=e=>establish('login',e);q('bootstrap-file').onchange=async e=>{const f=e.target.files?.[0];if(f)q('bootstrap-token').value=(await f.text()).trim()};boot();
